import 'package:flutter/material.dart';
import 'package:sehatak/core/localization/app_strings.dart';
import 'package:sehatak/core/constants/app_colors.dart';
import 'package:sehatak/core/services/unified_cart_service.dart';
class DrugDetailsScreen extends StatelessWidget{
 String _t(BuildContext context,String value)=>AppStrings.of(context).translate(value);
 final Map<String,dynamic> drug; const DrugDetailsScreen({super.key,required this.drug});
 String _text(BuildContext context,String k){final v=drug[k];return v==null||v.toString().trim().isEmpty?_t(context,'غير متوفر'):v.toString();}
 @override Widget build(BuildContext context){final dark=Theme.of(context).brightness==Brightness.dark;final alternatives=drug['alternatives'] is List?(drug['alternatives'] as List).map((e)=>e.toString()).where((e)=>e.isNotEmpty).toList():<String>[];final rx=drug['prescription']==true||drug['requiresPrescription']==true;return Scaffold(backgroundColor:dark?const Color(0xFF0B1121):const Color(0xFFF8FAFC),appBar:AppBar(title:Text(_text(context,'name')),backgroundColor:AppColors.primary,foregroundColor:Colors.white),body:SingleChildScrollView(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(height:150,width:double.infinity,decoration:BoxDecoration(color:dark?const Color(0xFF1A2540):Colors.grey[100],borderRadius:BorderRadius.circular(16)),child:const Center(child:Icon(Icons.medication,size:60,color:AppColors.primary))),const SizedBox(height:16),Row(children:[Expanded(child:Text(_text(context,'name'),style:TextStyle(fontSize:22,fontWeight:FontWeight.bold,color:dark?Colors.white:Colors.black87))),if(drug['price']!=null)Text(AppStrings.of(context).formatCurrency((drug['price'] as num).toDouble()),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:AppColors.primary))]),const SizedBox(height:8),Wrap(spacing:8,children:[if(_text(context,'category')!='غير متوفر')_chip(_text(context,'category'),AppColors.primary),if(rx)_chip(_t(context,'يحتاج وصفة'),Colors.red)]),const SizedBox(height:16),const Divider(),_detail(_t(context,'الاستخدام'),_text(context,'usage'),dark),_detail(_t(context,'الآثار الجانبية'),_text(context,'sideEffects'),dark),_detail(_t(context,'التفاعلات'),_text(context,'interactions'),dark),_detail(_t(context,'الجرعة'),_text(context,'dosage'),dark),_detail(_t(context,'الشركة المصنعة'),_text(context,'manufacturer'),dark),_detail(_t(context,'تاريخ الانتهاء'),_text(context,'expiry'),dark),_detail(_t(context,'التخزين'),_text(context,'storage'),dark),if(alternatives.isNotEmpty)...[const SizedBox(height:18),Text(_t(context,'بدائل الدواء'),style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),const SizedBox(height:8),Wrap(spacing:8,children:alternatives.map((a)=>_chip(a,AppColors.primary)).toList())],const SizedBox(height:24),SizedBox(width:double.infinity,child:ElevatedButton.icon(onPressed:_canAdd()?(){UnifiedCartService.instance.add(productId:(drug['id']??drug['productId']??drug['name']).toString(),name:_text(context,'name'),unitPrice:(drug['price'] as num?)?.toDouble()??0,requiresPrescription:rx);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text(_t(context,'تمت إضافة الدواء إلى السلة'))));}:null,icon:const Icon(Icons.add_shopping_cart),label:Text(_t(context,'إضافة إلى السلة')),style:ElevatedButton.styleFrom(backgroundColor:AppColors.primary,foregroundColor:Colors.white)))])));}
 bool _canAdd()=>drug['name']!=null&&drug['price'] is num&&drug['inStock']!=false;
 Widget _chip(String t,Color c)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:c.withOpacity(.1),borderRadius:BorderRadius.circular(20)),child:Text(t,style:TextStyle(fontSize:12,color:c,fontWeight:FontWeight.w600)));
 Widget _detail(String l,String v,bool dark)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:105,child:Text(l,style:TextStyle(fontSize:13,fontWeight:FontWeight.w600,color:dark?Colors.grey[400]:Colors.grey[600]))),Expanded(child:Text(v,style:TextStyle(fontSize:13,color:dark?Colors.white:Colors.black87,height:1.5)))]));
}